import java.text.Normalizer;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Pattern;

/**
 * Narrows the customer list by name and by status. A customer matches when it
 * satisfies both parts.
 *
 * <ul>
 *   <li>Name: the text is split on whitespace into terms, and every term must be
 *       a substring of the customer's first name or of the last name. Matching
 *       ignores case and accents, so {@code makinen} matches {@code Mäkinen}.</li>
 *   <li>Status: with one or more statuses listed, the customer's status must be
 *       one of them.</li>
 * </ul>
 *
 * @param name     the text typed into the name filter; blank matches every name
 * @param statuses the statuses to show; empty shows every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** The filter that matches every customer. */
    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = Set.copyOf(statuses);
    }

    /**
     * Returns a test for this filter. Build it once per query, not once per customer:
     * the name is split and folded here.
     */
    public Predicate<Customer> asPredicate() {
        List<String> terms = WHITESPACE.splitAsStream(name)
                .filter(term -> !term.isEmpty())
                .map(CustomerFilter::fold)
                .toList();
        return customer -> matchesStatus(customer) && matchesName(customer, terms);
    }

    private boolean matchesStatus(Customer customer) {
        return statuses.isEmpty() || statuses.contains(customer.status());
    }

    private static boolean matchesName(Customer customer, List<String> terms) {
        String firstName = fold(customer.firstName());
        String lastName = fold(customer.lastName());
        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
    }

    /** Lower-cases the text and strips accents, so {@code Joséphine} folds to {@code josephine}. */
    private static String fold(String text) {
        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }
}
